import json

from ..report.testdata import TestData
from ..robot_compatibility import TestCase
from ..utils.tags import get_single_tag_from_test, get_tags_from_test
from ..utils.variables import (
    get_json_env_variable_value,
    get_test_qc_param_from_cm_test_information,
)
from pprint import pformat
from ..utils.logger import logger


def _normalize_name(name: str) -> str:
    return name.replace(" ", "_")


class BaseBuilder:
    def _convert_result(self, status):
        """
        The status is `NOT_RUN` in RF<4.0.0 and `NOT RUN` in newer versions
        """
        mapping = {
            "PASS": "passed",
            "FAIL": "failed",
            "NOT_RUN": "not run",
            "NOT RUN": "not run",
            "SKIP": "skip",
        }
        return mapping[status]


class TestBuilder(BaseBuilder):
    """
    Builds proper report data for a test
    """

    __test__ = False

    def __init__(self, test_line, environment):
        """
        :param TestLine         test_line:      TestLine class object.
        :param Environment      environment:   Environment class object.
        """
        self._ph = "" if environment.phase is None else environment.phase
        self.bts_sw_version = test_line.bts_sw_version
        self._secondary_versions = test_line.secondary_versions
        self._links = environment.links
        self._add_info = environment.add_info
        self._robotlte_revision = environment.robotlte_revision
        self._username = environment.username
        self._no_qc = environment.no_qc
        self._cm_test_information = self._get_cm_test_information_data()
        self._rfsw_build = environment.rfsw_build
        self.simulators = test_line.simulators_versions

    def build_data(
            self,
            test: TestCase,
            suite_prefix: str,
            test_case_names_in_automation_options: list[str],
    ):
        """
        Build the test section for the Reporting Portal report.

        :param TestCase     test:           Test case object generated by the Robot Framework.

        :return: TestData dictionary like type created based on the information from the Test case object.
        :rtype:  TestData
        """
        test_data = TestData()
        test_data.result = self._convert_result(test.status)
        if test_data.result == "skip":
            return test_data.result, test.name
        test_data.name = test.name
        test_data.username = self._username
        test_data.source_control_revision = self._robotlte_revision
        test_data.doc = test.doc
        test_data.starttime = test.starttime
        test_data.endtime = test.endtime
        test_data.fail_message = test.message
        test_data.features_covered = get_tags_from_test(test, "FT")
        test_data.phase = get_single_tag_from_test(test, "PH") or self._ph
        test_data.ca = get_single_tag_from_test(test, "CA")
        test_data.build = self.bts_sw_version
        test_data.build_tag = ""
        test_data.iphy = self.simulators["iphy"]["version"]
        test_data.cus = self.simulators["cus"]["version"]
        test_data.airphone = ""
        test_data.parameters2 = self._secondary_versions
        test_data.add_info = self._create_add_info()
        test_data.links = self._links
        test_data.rfsw_build = self._rfsw_build

        qualified_name = f"{suite_prefix}.{test.name}"
        qualified_name_normalized = f"{_normalize_name(suite_prefix)}.{test.name}"
        test_data.qualified_name = (
            qualified_name if qualified_name in test_case_names_in_automation_options
            else qualified_name_normalized if qualified_name_normalized in test_case_names_in_automation_options
            else ""
        )

        if not self._no_qc:
            if self._cm_test_information:
                test_name = test_data.qualified_name or test.name
                test_data.qc_id = get_test_qc_param_from_cm_test_information(
                    self._cm_test_information, test_name, "id"
                )
                test_data.qc_domain = get_test_qc_param_from_cm_test_information(
                    self._cm_test_information, test_name, "qc_domain"
                )
                test_data.qc_project = get_test_qc_param_from_cm_test_information(
                    self._cm_test_information, test_name, "qc_project"
                )
            else:
                test_data.qc_id = get_single_tag_from_test(test, "QC")
                test_data.qc_domain = get_single_tag_from_test(test, "QCD")
                test_data.qc_project = get_single_tag_from_test(test, "QCP")
                test_data.multi_qc = (
                    True if get_single_tag_from_test(test, "MQC") else False
                )

        return test_data

    def _create_add_info(self):
        if self._add_info:
            return ["UTE", self._add_info]
        return ["UTE"]

    @staticmethod
    def _get_cm_test_information_data():
        cm_test_information = get_json_env_variable_value("CM_TEST_INFORMATION", {})
        logger.debug("CM_TEST_INFORMATION data:\n%s", pformat(cm_test_information))
        return cm_test_information


class SuiteBuilder(BaseBuilder):
    """
    Builds proper report data for a suite
    """

    def __init__(self, environment):
        self._ca = environment.competence_area
        self._tl = environment.testline
        self._suite_hierarchy = []

        self.test_case_names_in_automation_options = self._get_test_case_names_in_automation_options()

    def build(self, suite):
        """
        Build the suite section for the Reporting Portal report.

        :param TestSuite suite: Test suite object generated by the Robot Framework.

        :return: Initial dictionary for a suite in which the test_cases field is empty.
        :rtype:  dictionary
        """
        return {
            "name": self.get_suite_prefix(),
            "doc": suite.doc,
            "starttime": suite.starttime,
            "endtime": suite.endtime,
            "ca": self._ca or "",
            "testline": self._tl,
            "result": self._convert_result(suite.status),
            "test_cases": [],
            "metadata_for_symptom_files": {},
            "tool": "",
            "cm_sign": {},
            "cm_tags": [],
            "cm_artifacts": [],
            "cm_execution_id": "",
            "robot_repo_revision": "",
            "rtg_build": "",
        }

    def enter_suite(self, suite_name):
        """
        Method needed to create proper suite path.

        :note: Robot Framework supports multiple suite levels, but Reporting Portal doesn't need this information.

        :note: Method have to be executed for every test suite when it started like below:

        ::

               test_suite_builder.enter_suite(suite.name)

               Above action allows TestSuiteBuilder to create proper suite path like TS1.TS2 for two levels.

        :param string suite_name: Suite name
        """
        self._suite_hierarchy.append(suite_name)

    def exit_suite(self):
        """
        Method to exit_suite last suite from suite hierarchy created via enter_suite method.

        :note: Method have to be executed for every test suite when it stopped like below:

        ::

            test_suite_builder.exit_suite()
        """
        if len(self._suite_hierarchy) > 0:
            self._suite_hierarchy.pop()

    def get_suite_prefix(self):
        return ".".join(self._suite_hierarchy)

    @staticmethod
    def _get_test_case_names_in_automation_options() -> list[str]:
        cm_test_information = get_json_env_variable_value("CM_TEST_INFORMATION", {})
        if not cm_test_information:
            return []
        names = []
        for t in cm_test_information["tests"]:
            automated_options = next(p["value"] for p in t["parameters"] if p["name"] == "automation_options")
            automated_options = json.loads(automated_options)
            names.append(automated_options["test_case_name"])
        return names
